              const since = r.since ? stratDateTxt(r.since).replace(/,\s*\d{4}$/, "") : "";
              return `<b>${esc(r.wl)}</b>${r.hit != null ? ` (<b>${stratPct(r.hit)}</b>)` : ""}${since ? ` since ${esc(since)}` : ""}, graded in the open`;
